export const getFetch = (url) => {
  return new Promise((resolve, reject) => {
    try {
      fetch(url)
        .then(function (response) {
          try {
            const headers = response.headers
            if (!window.tech) {
              window.tech = {}
            }
            let sessionAllowConcatResource =
              sessionStorage?.getItem?.('concatRes') ||
              sessionStorage?.getItem?.('allowConcatResource')
            // 标识开启 openResty的资源合并 sessionStorage 若有配置则concat优先
            if (sessionAllowConcatResource !== null && sessionAllowConcatResource !== undefined) {
              window.tech.allowConcatResource =
                sessionAllowConcatResource === 'true' || sessionAllowConcatResource === true
                  ? true
                  : false
            } else if (
              headers.get('allow-concat-resource') ||
              headers.get('Allow-Concat-Resource')
            ) {
              window.tech.allowConcatResource = true // 标识开启 openResty的资源合并
            }
          } catch (e) {}
          return response.json()
        })
        .then(function (json) {
          resolve(json)
        })
        .catch(function (err) {
          console.log(' ===  getFetch error2 ==', err, url)
          resolve()
          // reject(err);
        })
    } catch (e) {
      console.log(' ===  getFetch error ==', e)
      resolve()
    }
  })
}

export const appsToLocalUrl = (apps) => {
  let curApps = apps
  try {
    for (let k1 in curApps) {
      for (let k2 in curApps[k1]) {
        for (let k3 in curApps[k1][k2]) {
          let tmpUrl = curApps[k1][k2][k3]
          if (tmpUrl.indexOf('/umdComps/') !== -1) {
            tmpUrl = tmpUrl.split('/umdComps/')[1]
            curApps[k1][k2][k3] = '/umdComps/' + tmpUrl
          } else if (tmpUrl.indexOf('/') !== 0) {
            // 兼容处理local情况里面没有/umdComps/情况
            curApps[k1][k2][k3] = '/umdComps/' + k3 + '/config/app.json'
          }
        }
      }
    }
  } catch (e) {
    console.log(' === appsToLocalUrl error == ', e)
  }
  return curApps
}

