const jsToJson = (data) => {
  return JSON.stringify(
    data,
    function (key, value) {
      let fnBody
      if (value instanceof Function || typeof value == 'function') {
        fnBody = value.toString()
        return fnBody // .replace(/\n\s\s/g, '')
      } else if (value instanceof RegExp) {
        fnBody = value.toString()
        return fnBody // .replace(/\n\s\s/g, '')
      }
      return value
    },
    2
  )
}

