// 合并list.json到apps.json
export const mergeListToApps = async (apps) => {
  let listJson = {}
  if (customProcess?.env === 'local') {
    // build:local和start:local还取list.json,其他情况不取
    if (window.techInnerAppList) {
      listJson = window.techInnerAppList
    } else {
      listJson = await getFetch('/config/list.json?v=' + new Date().getTime())
    }
  }
  // 把内置app路径本地化
  let localListJson = JSON.parse(JSON.stringify(listJson))
  if (localListJson.apps) {
    localListJson.apps = appsToLocalUrl(localListJson.apps)
  }
  apps.apps = {
    ...(apps.apps || {}),
    ...(localListJson?.apps || {})
  }
  apps.innerApp = {
    ...(apps.innerApp || {}),
    ...(localListJson?.innerApp || {})
  }
}
