// 处理开发环境卡问题 console要运行 techRefreshDev() 先跳到127 ip再跳回来解决
try {
  if (location.href.indexOf('?refreshDevSrcHref=') !== -1) {
    let refreshDevSrcHref = location.href.split('?refreshDevSrcHref=')[1]
    setTimeout(() => {
      location.href = decodeURIComponent(refreshDevSrcHref)
    }, 1000)
  }
  window.techRefreshDev = function () {
    let jumpHref =
      location.protocol +
      '//127.0.0.1:' +
      (location.port || 80) +
      '?refreshDevSrcHref=' +
      encodeURIComponent(location.href)
    location.href = jumpHref
  }
  if (process?.env === 'development') {
    document.addEventListener('keydown', function (event) {
      // 判断是否按下 Ctrl 和 F 键
      if (event.ctrlKey && event.keyCode === 82) {
        // 执行您的自定义操作
        console.log('ctrl+r 已被按下 触发开发刷新')
        event.preventDefault() // 阻止默认行为（如果需要）
        window.techRefreshDev()
      }
    })
  }
} catch (e) {}

window.techCoreRender = { loadAsset, loadApps }
window.techCoreRunTime = { Core, getUrlParam, LowcodeRender, mergeOptions, mergeExtend }
window.techUi = webLib
window.ELEMENT.Message = webLib.techMessage
const appsJsonLocalUrl = '/config/apps.json?v=' + new Date().getTime()

const init = async () => {
  // 开发环境才加载
  if (window?.tech?.$envInfo?.dev) {
    if (location.href.indexOf('?pageId=iidp_dev_open_page') !== -1) {
      // 打开弹窗页内容处理 （点击 开发 按钮后的逻辑）
      await import('./js/devTool/devPageContent.js')
      return
    }
    // 点击 开发 按钮前的逻辑
    // 开发环境才加载调试信息
    await import('./js/devInfo.js')
    // 开发环境才加载调试工具入口
    await import('./js/devTool/devTool.js')
  }
  // 环境先写死 master 后面 生成环境master 灰度环境grey 测试环境test 开发环境dev
  // 对应apps.json的master
  let env = 'master'
  if (!window.tech) {
    window.tech = {}
  }
  window.tech.env = env
  let apps = {}
  if (tech?.TABIFRAME?.inner) {
    apps = window.tech.srcApps
  } else {
    // 若apps.json已经预加载了则不重复请求
    if (window._iidpPreloadApps) {
      apps = window._iidpPreloadApps
    } else {
      apps = await getFetch(appsJsonLocalUrl)
    }
    try {
      let curUrl = new URL(location.href)
      let topParams = new URLSearchParams(curUrl.search)
      let srcFrontHost = topParams.get('frontHost')
      if (srcFrontHost) {
        // 若有frontHost配置 则再请求一次frontHost的的apps.json 为了获取判断是否开启 openResty的资源合并标识 Allow-Concat-Resource
        srcFrontHost = decodeURIComponent(srcFrontHost)
        let frontAppsUrl =
          location.protocol +
          '//' +
          srcFrontHost.split('/')[0] +
          '/config/apps.json?t=' +
          new Date().getTime()
        await getFetch(frontAppsUrl)
      }
    } catch (e) {}
    try {
      if (process?.env === 'development') {
        if (apps?.global?.TABIFRAME) {
          // 配置了 tab iframe的开发模型
          apps.global.TABIFRAME.host = location.protocol + '//' + location.host
          apps.global.TABIFRAME.contentHost =
            location.protocol + '//127.0.0.1:' + (location.port ? location.port : '80')
        }
      }
    } catch (e) {}
    window.tech.srcApps = JSON.parse(JSON.stringify(apps))
  }

  // console.log(' === apps == ', apps);
  // console.log(' === Vue == ', Vue);
  // 获取全局变量参数
  let globalParams = {
    ...apps,
    ...(apps?.global || {}),
    ...(apps?.global?.[env] || {})
  }

  if (!window.tech) {
    // 全局变量挂window tech
    window.tech = {}
  }
  window.tech = {
    // 全局变量挂window tech
    ...window.tech,
    ...globalParams
  }

  if (tech?.TABIFRAME) {
    if (location.href.indexOf('tabIframeInner') !== -1) {
      // 重新加回 inner 标识
      tech.TABIFRAME.inner = true
    } else {
      tech.TABIFRAME.inner = false
    }
  }

  // 当前环境模式
  // console.log(' 当前环境 process == ', process);
  // console.log(' 当前环境模式 customProcess == ', customProcess);

  Vue.$store = store
  Vue.config.productionTip = false

  // 加载模板应用
  const templateAppName = globalParams.templateApp || 'EmptyApp'
  let templateApp = {}

  // 若:api脚本命令运行 则从api接口获取apps配置
  if (customProcess?.env === 'base') {
    if (tech?.TABIFRAME?.inner) {
      apps = window.tech.srcOutApps
    } else {
      apps = await getApiApps(Vue)
      window.tech.srcOutApps = JSON.parse(JSON.stringify(apps))
    }
  } else if (customProcess?.env === 'local') {
    // app连接本地修改
    if (apps?.apps) {
      apps.apps = appsToLocalUrl(apps.apps)
    }
    await mergeListToApps(apps)
  } else {
    await mergeListToApps(apps)
  }

  // 开发态情况的 npm start  npm run start:local
  // 拼接 appsDetail 让按需加载资源的 effectPaths 生效
  if (
    process?.env === 'development' &&
    (customProcess?.env === 'start' || customProcess?.env === 'local')
  ) {
    await devMakeAppsDetail(apps, env)
  }

  // 存起最终处理后apps到window.tech_apps
  window.tech_apps = apps
  // 加载语言包
  await loadLang(globalParams, apps)

  if (customProcess?.baseFromNodeModule) {
    
    if (templateAppName !== 'EmptyApp') {
      try {
        import('@tech/t-base/' + templateAppName + '/style.css')
      } catch (e) {}
    }
    templateApp = await import(
      '@tech/t-base/' + templateAppName + '/build.' + templateAppName + '.es.js'
    )
    
  } else {
    
  }

  templateApp = templateApp?.default
  // console.log(' === 模板应用 == ', templateApp);
  Vue.use(templateApp)

  // 国际化
  Vue.use(vueI18n)
  Vue.use(Element, { locale })
  Vue.use(Element, {
    i18n: (key, value) => i18n.t(key, value)
  })
  ElementLocale.i18n((key, value) => i18n.t(key, value))
  ElementLocale.use(locale)
  window.WujieVue = WujieVue
  Vue.use(WujieVue)

  // 重置 Vue.prototype.$t 避免_t报错
  if (window?.Vue?.prototype?.$t && !window?._techReset$t) {
    window.Vue.prototype.$t = (key) => {
      return Tech.$t(key)
    }
    window._techReset$t = true
  }

  // 自定义处理vue内部错误打印
  Vue.config.errorHandler = (err, vm, info) => {
    let notShow = [
      'event handler for "getProfileUserInfo"',
      'event handler for "getProfileUserInfo"',
      'beforeDestroy hook'
    ]
    // console.log(' === info ==' + info + '')
    if (notShow.indexOf(info + '') === -1) {
      // 不在notShow数组中才打印
      console.error('Error in Vue: err: ', err)
      // console.error('Error in Vue: info: ', info)
      // console.error('Error in Vue: vm: ', vm)
    }
  }

  // const { setupApp, preloadApp, bus } = WujieVue;

  // console.log(' ==== __dirname == ', __dirname);

  // let a = 'base';
  // let testBase = await import('../../apps/'+a+'/test.js');
  // console.log(' ==== testBase == ', testBase);

  let localOptions = null // 本地扩展参数
  if (process?.env === 'development') {
    // 动态导入genAppEffect.js
    await import('./js/genAppEffect.js')
    // 方便本地开发调试 打本地包需要接口这个判断
    // 从 apps 里面的self拼接本地扩展应用名
    try {
      // console.log(' === customProcess  ', customProcess)
      if (customProcess?.env === 'base' && customProcess?.app !== 'onlyMarketApp') {
        // start:base情况 重新构造self
        let devSelfApps = window?.tech?.srcApps?.self?.[env]
        if (devSelfApps) {
          if (!apps.self) {
            apps.self = {}
          }
          if (!apps.self[env]) {
            apps.self[env] = {}
          }
          Object.keys(apps?.apps || {}).forEach((mName) => {
            Object.keys(apps?.apps?.[mName]?.[env] || {}).forEach((cName) => {
              let mName2 = cName.startsWith('tech-') ? cName.replace('tech-', '') : cName
              if (devSelfApps?.[mName2] !== undefined) {
                apps.self[env][mName2] = devSelfApps[mName2]
              }
            })
          })
        }
      }
    } catch (e) {}
    if (apps?.self?.[env]) {
      let selfObjs = apps.self?.[env] || {}
      localOptions = []
      // 若需要调整本机开发app加载顺序 则调整扩展工程 config/apps.json里面的 self.master里面app排列顺序
      for (let selfAppName in selfObjs) {
        // 若为空字符串则提前加载
        if (!selfObjs[selfAppName]) {
          if (customProcess?.baseFromNodeModule) {
            
          } else {
            
          }
        } else {
          // 否则存进 window.techDevApps 全局变量
          if (!window.techDevApps) {
            window.techDevApps = []
          }
          let curComp = null
          if (customProcess?.baseFromNodeModule) {
            
          } else {
            
          }
          if (curComp) {
            window.techDevApps.push({
              name: selfAppName,
              path: selfObjs[selfAppName],
              comp: curComp
            })
          }

          // *sub 子资源拆分 开发环境子资源存进 window.techDevAppsSub
          if (!window.techDevAppsSub) {
            window.techDevAppsSub = []
          }
          
          
        }
      }
      // console.log(' === window.techDevAppsSub == > ', window.techDevAppsSub)
    }
  }
  initLocalEndView(apps)
  const paramOptions = await templateApp.loadApps(apps, Vue, localOptions)
  // console.log(' === 全局变量 == ', window.tech);

  if (templateApp?.loadAsset) {
    await templateApp.loadAsset(paramOptions, Vue)
  }

  // console.log(' ==== paramOptions === ', paramOptions);
  Vue.prototype.$templageAppName = templateApp?.name || ''
  Vue.prototype.$paramOptions = paramOptions

  const router = new VueRouter({
    base: globalParams.routerBase || '/',
    mode: 'history',
    routes
  })

  // Vue.mixin({
  //   destroyed() {
  //     if (!this.config) return
  //     Object.entries(this.config).forEach(([, val]) => {
  //       if (val && ['object', 'function'].includes(typeof val)) {
  //         // 删除收集依赖对象，断开引用，使 vueComponent 可以正常被 GC
  //         delete val.__ob__
  //       }
  //     })
  //   }
  // })

  window.VueInstance = new Vue({
    store,
    router,
    i18n,
    render: (h) => h(App)
  }).$mount('#base')
}

if (location.href.indexOf('tabIframeInner') !== -1) {
  if (window?.tech?.hasIframeMsg) {
    init()
  } else {
    window.tech_init = init
  }
  // 定义接收其他iframe的父级信息方法
  window.tech_get_parent_msg = (data, event) => {
    switch (data.type) {
      case 'TABIFRAME_THEME': // 同步皮肤
        let node = tech_app.page.getNode(data.clickNodeId)
        node?.instance?.click()
        break
      case 'TABIFRAME_OPEN_MENU': // 同步打开的菜单
        const menu = tech_app.page.getNode('menu_meta_siderbar')
        window.tech_tmp_pathname = data.app.activeUrl
        if (window?.tech_app?.updateOptions) {
          window.tech_app.updateOptions({ updateSchema: false }).then((res) => {
            menu.instance.openLinkNoFrameFn(data.app, true, { fromInnerOpenMenu: true })
            window.tech_tmp_pathname = null
          })
        } else {
          menu.instance.openLinkNoFrameFn(data.app, true, { fromInnerOpenMenu: true })
        }
        break
      case 'TABIFRAME_LOGOUT': // 同步退出登陆
        window.Tech.cookies.remove('userInfo')
        window.Tech.cookies.remove('sieIiotToken')
        break
      case 'TABIFRAME_FN': // 同步运行字符串方法 父传到子运行
        if (data.fn && event.origin === tech?.TABIFRAME?.host) {
          if (Object.prototype.toString.call(data.fn) === '[object String]') {
            try {
              data.fn = new Function('return ' + data.fn)().bind(window)
            } catch (e) {
              console.log(' === TABIFRAME_FN inner 父传到子运行 error == ', data.fn, e)
            }
          }
          data.fn(data.params || {})
        }
        break
      default:
        break
    }
  }
} else {
  // 原来的情况
  init()
}
