if (!window.Tech) {
  window.Tech = {}
}
if (!window.tech) {
  window.tech = {}
}
// 获取环境变量方法
window.Tech.getEnvInfo = () => {
  let reObj = {}
  try {
    reObj.env = process?.env
    reObj.customEnv = customProcess?.env
    reObj.runtimeDev = false // 是否运行时进入开发模式
    reObj.dev = false // 是否处于开发模式

    // 若为development环境 则dev为true
    if (reObj.env === 'development') {
      reObj.dev = true
    }

    // 若有问号参数 或 session iidpDev则接替dev
    const urlParams = new URLSearchParams(window.location.search)
    let urlDev = urlParams.get('iidpDev')
    if (urlDev !== null) {
      sessionStorage.setItem('iidpDev', urlDev)
    }
    let sessionDev = sessionStorage?.getItem?.('iidpDev')
    if (sessionDev !== null && sessionDev !== undefined) {
      reObj.runtimeDev = sessionDev === 'true'
      reObj.dev = reObj.runtimeDev
    }
  } catch (e) {
    console.log(' === getEnvInfo error === ', e)
  }
  return reObj
}
// 存储环境变量
window.tech.$envInfo = window.Tech.getEnvInfo()
