// 注册拼接资源方法
if (!window.Tech) {
  window.Tech = {}
}
if (!window.tech) {
  window.tech = {}
}
// 存放缓存的变量
if (!window.tech.__concatCache) {
  window.tech.__concatCache = {}
}
// 存放 Service Worker message 监听器
if (!window.tech.__swMessageListener) {
  window.tech.__swMessageListener = null
}

// 按数组请求  入参支持多个数组例如
// [{type:'js', paths:['http://xx.js', 'http://xx2.js'], time: ['2020-xx', '2020-xx']}, {type:'css', paths:['http://xx.css', 'http://xx2.css']}, , {type:'json', paths:['http://xx.json', 'http://xx2.json']}]
window.Tech.reqConcatRes = async (arrObj, options = {}) => {
  if (window?.tech?.allowConcatResource) {
    // 判断了开启标识才运行
    // 处理arr做过大拆分 避免超出浏览器url的最大字符串限制
    let splitStr = options?.splitStr || '/umdComps/'
    let reqInfo = options?.info || 'req'
    let arr = []
    const chunkSize = 30 // 最多一次请求多少个
    for (let n = 0; n < arrObj.length; n++) {
      if (splitStr) {
        // 过滤有splitStr的
        arrObj[n].paths = arrObj[n].paths.filter((it, pos) => {
          let hasSplitStr = it?.indexOf?.(splitStr) > -1
          if (!hasSplitStr && arrObj?.[n]?.time?.[pos] !== undefined) {
            arrObj[n].time[pos] = 'noUse'
          }
          return hasSplitStr
        })
        arrObj[n].time = arrObj[n].time.filter((it) => it !== 'noUse' && it !== undefined)
        // 根据splitStr调整路径
        arrObj[n].paths = arrObj[n].paths.map((it) => splitStr + it?.split?.(splitStr)?.[1])
      }
      for (let m = 0; m < arrObj[n].paths.length; m += chunkSize) {
        let pChunk = arrObj[n].paths.slice(m, m + chunkSize)
        let tChunk = null
        if (arrObj[n].time) {
          tChunk = arrObj[n].time.slice(m, m + chunkSize)
        }
        arr.push({
          type: arrObj[n].type,
          paths: pChunk,
          time: tChunk
        })
      }
    }
    // console.log(' === arr == ', arr)

    let reqArr = []
    let apiPre = '/concatResource?info=' + reqInfo // 两层缓存 浏览器 和 nginx服务器都通过url缓存
    try {
      let curUrl = new URL(location.href)
      let topParams = new URLSearchParams(curUrl.search)
      let srcFrontHost = topParams.get('frontHost')
      if (srcFrontHost) {
        // 若有frontHost配置 则再请求一次frontHost的的apps.json 为了获取判断是否开启 openResty的资源合并标识 Allow-Concat-Resource
        srcFrontHost = decodeURIComponent(srcFrontHost)
        apiPre = location.protocol + '//' + srcFrontHost.split('/')[0] + apiPre
      }
    } catch (e) {}

    // 将各种时间格式转换为时间戳数字进行比较
    let parseTimeToTimestamp = (val) => {
      // null/undefined 转为 0
      if (val === null || val === undefined) {
        return 0
      }
      // 字符串处理
      if (typeof val === 'string') {
        let str = val.trim()
        // 空字符串转为 0
        if (!str) {
          return 0
        }
        // 先解码URL编码（如 2026-01-4%2010%3A17%3A17）
        try {
          str = decodeURIComponent(str)
        } catch (e) {
          // 解码失败则保持原值
        }
        // 如果是纯数字字符串（时间戳），直接转数字
        if (/^\d+$/.test(str)) {
          return Number(str)
        }
        // 尝试解析日期字符串（如 2026-01-4 10:17:17）
        const timestamp = new Date(str).getTime()
        return isNaN(timestamp) ? 0 : timestamp
      }
      // 数字直接返回
      if (typeof val === 'number') {
        return isNaN(val) ? 0 : val
      }
      return 0
    }

    for (let i = 0; i < arr.length; i++) {
      let item = arr[i]
      let type = item.type
      let paths = item.paths
      let t = item.time
      // 控制缓存的时间戳t
      if (!t) {
        t = new Date().getTime()
      }

      if (Object.prototype.toString.call(t) === '[object Array]') {
        try {
          t = t.map((it) => {
            return parseTimeToTimestamp(it)
          })
        } catch (e) {
          console.log(' === replace -x- error === ', e)
        }
        // 若为数组 则拿排序后最大那个时间
        t.sort()
        t = t[t.length - 1]
      }
      if (type === 'js') {
        reqArr.push(
          window.Tech.asyncLoadJs(
            apiPre + '&type=' + type + '&t=' + t + '&files=' + paths.join(','),
            document
          )
        )
      } else if (type === 'css') {
        reqArr.push(
          window.Tech.asyncLoadCss(
            apiPre + '&type=' + type + '&t=' + t + '&files=' + paths.join(','),
            document
          )
        )
      } else if (type === 'json') {
        reqArr.push(
          window.Tech.getFetch(apiPre + '&type=' + type + '&t=' + t + '&files=' + paths.join(','))
        )
      }
    }
    try {
      const resArr = await Promise.allSettled(reqArr)
      // let failIndexs = []
      resArr.map((result, index) => {
        if (result.status !== 'rejected') {
          let item = arr[index]
          let type = item.type
          let paths = item.paths
          let value = result.value
          if (type === 'js') {
            // js情况构造js标签渲染
            paths.map((it, pos) => {
              window.tech.__concatCache[it] = true
            })
          } else if (type === 'css') {
            // css情况构造css标签渲染
            paths.map((it, pos) => {
              window.tech.__concatCache[it] = true
            })
          } else if (type === 'json') {
            // json情况按数组位置赋值
            let valueArr = value
            if (Object.prototype.toString.call(valueArr) === '[object Array]') {
              paths.map((it, pos) => {
                window.tech.__concatCache[it] = valueArr[pos]
              })
            } else if (valueArr === undefined) {
              console.log(' === Error reqConcatRes json res content Error :', arr[index])
            }
          }
        }
      })
    } catch (e) {}
    // 异步
    // await new Promise((resolve) => setTimeout(resolve, 0))
  }
}

window.Tech.swReqConcatRes = (swConcatPaths) => {
  try {
    return new Promise((resolve) => {
      let baseUrl = location.origin
      try {
        let curUrl = new URL(location.href)
        let topParams = new URLSearchParams(curUrl.search)
        let srcFrontHost = topParams.get('frontHost')
        if (srcFrontHost) {
          // 若有frontHost配置 则再请求一次frontHost的的apps.json 为了获取判断是否开启 openResty的资源合并标识 Allow-Concat-Resource
          srcFrontHost = decodeURIComponent(srcFrontHost)
          baseUrl = location.protocol + '//' + srcFrontHost.split('/')[0]
        }
      } catch (e) {}
      // console.log(' === swReqConcatRes - baseUrl === ', baseUrl)
      const pendingRequests = new Map()
      // 如果已存在监听器，先移除旧的
      if (window.tech.__swMessageListener) {
        navigator.serviceWorker.removeEventListener('message', window.tech.__swMessageListener)
        window.tech.__swMessageListener = null
      }
      // 创建新的监听器并保存到全局变量
      window.tech.__swMessageListener = (event) => {
        const { id, result, error, evalPaths } = event.data
        if (error) {
          reject(new Error(error))
        }
        // console.log(' === swMessageListener === ', event.data)
        if (evalPaths) {
          // // console.log(' ==== get evalPaths === ', evalPaths)
          // try {
          //   evalPaths.map((it) => {
          //     if (it.endsWith('.js')) {
          //       let jsPath = window.Tech.getSWUsefulPath(it)
          //       if (jsPath) {
          //         // 不能提前eval语法 因为里面可能有多语言变量定义
          //         // window.Tech.asyncLoadJsNew(jsPath, document)
          //       }
          //     } else if (it.endsWith('.css')) {
          //       let cssPath = window.Tech.getSWUsefulPath(it)
          //       if (cssPath) {
          //         window.Tech.asyncLoadCssNew(cssPath, document)
          //       }
          //     }
          //   })
          // } catch (e) {
          //   console.log(' ==== loadFirstAppArr error == ', e)
          // }
        } else if (result) {
          resolve(result)
        }
      }
      // 添加新的监听器
      navigator.serviceWorker.addEventListener('message', window.tech.__swMessageListener)
      new Promise((resolve, reject) => {
        const id = Date.now()
        pendingRequests.set(id, { resolve, reject })
        window.iidpSwRegistration.active.postMessage({
          type: 'SW_CONCAT_PATHS',
          data: {
            paths: swConcatPaths,
            delimiter: '/'
          },
          options: {
            concatLoadAppsJsNumber: window?.tech?.concatLoadAppsJsNumber || null, // js最多一次请求个数
            baseUrl
          },
          id: id
        })
      })
    })
  } catch (error) {}
}
// 检测拼接资源缓存是否存在
window.Tech.getConcatRes = (checkPath, splitStr = '/umdComps/') => {
  if (window?.tech?.allowConcatResource) {
    let tmpPath = checkPath
    if (tmpPath?.indexOf('?') !== -1) {
      tmpPath = tmpPath.split('?')[0]
    }
    let resPath = splitStr + tmpPath?.split?.(splitStr)?.[1]
    // 判断了开启标识才运行
    let res = window?.tech?.__concatCache?.[resPath]
    if (Object.prototype.toString.call(res) === '[object Object]') {
      if ((res?.___error + '').indexOf('notFound~~') !== -1) {
        console.log(checkPath, '加载失败')
        return {} // json情况失败则返回空对象
      }
    }
    return res
  }
}

// 获取新路径
window.Tech.getSWUsefulPath = (swPath) => {
  try {
    let compName = swPath.split('/umdComps/')[1].split('/')[0]
    // console.log(' === compName == ', compName)
    let compObj = null
    if (compName) {
      for (let n in window?.tech?.srcOutApps?.appsDetail || {}) {
        for (let m in window?.tech?.srcOutApps?.appsDetail?.[n]?.[window?.tech?.env || 'master'] ||
          {}) {
          if (m === compName) {
            compObj = window.tech.srcOutApps.appsDetail[n][window?.tech?.env || 'master'][m]
            break
          }
        }
        if (compObj) {
          break
        }
      }
    }
    // console.log(' === compObj === ', compObj)
    if (compObj?.view_file_json?.assets) {
      let appJsonPath = ''
      try {
        appJsonPath = compObj.view_file
      } catch (e) {}
      if (!appJsonPath) {
        return
      }
      let prePath = '' // 获取的前缀路径
      try {
        prePath = appJsonPath.split('config/app.json')[0]
      } catch (e) {}
      // console.log(' === prePath == ', prePath)
      if (swPath.endsWith('.js') && compObj?.view_file_json?.assets?.js?.[0]) {
        return prePath + compObj?.view_file_json?.assets?.js?.[0]
      } else if (swPath.endsWith('.css') && compObj?.view_file_json?.assets?.css?.[0]) {
        return prePath + compObj?.view_file_json?.assets?.css?.[0]
      }
    }
  } catch (e) {
    // console.log(' ==== getSWUsefulPath error === ', e)
  }
}
