// 注册大资源方法
export const regBigRes = () => {
  // 异步获取文件预览大资源
  window.Tech._getFilePreviewBigRes = (type) => {
    if (type === 'doc') {
      return import('./filePreviewRes/packages/docx/index.js')
    } else if (type === 'excel') {
      return import('./filePreviewRes/packages/excel/index.js')
    } else if (type === 'pdf') {
      return import('./filePreviewRes/packages/pdf/index.js')
    }
  }
  // 异步获取富文本编辑器大资源
  window.Tech._getRichTextBigRes = async (type) => {
    let res = await import('@wangeditor/editor-for-vue')
    if (type === 'editor') {
      return res.Editor
    } else if (type === 'toolbar') {
      return res.Toolbar
    }
  }
}
