import './theme_default.css'
import './theme_dark.css'

//js具体判断使用哪个主题
const styleDefine = JSON.parse(localStorage.getItem('TECH-THEME')) //缓存的主题
if (styleDefine?.value && styleDefine.value == 'sie2') {
  //暗色系紧凑型主题
  document.documentElement.setAttribute('theme', 'themedark')
} else {
  document.documentElement.setAttribute('theme', 'themedefault')
}
