// key如果没有键值对命中
// 先判断是否有第二个默认字符串参数 有则返回
// 否则 返回最后.后面内容
window.Tech.$t = (key, defaultStr = null) => {
  try {
    let distStr = window.Tech.LANG.t(key)
    if (distStr === key) {
      if (key.indexOf('.') !== -1) {
        if (defaultStr !== null) {
          return defaultStr
        } else {
          let keyArr = key.split('.')
          return keyArr?.[keyArr.length - 1] || distStr
        }
      } else {
        return distStr
      }
    } else {
      return distStr
    }
  } catch (e) {
    return key
  }
}

