// 获取URL参数
function getURLParameters() {
  const urlParams = new URLSearchParams(window.location.search)
  const keys = []
  for (const key of urlParams.keys()) {
    keys.push(key)
  }
  return keys
}

// 加载语言包
export const loadLang = async (appsJSONObj, apps) => {
  // 获取url？后面的参数，如果存在noLoadI18n就不加载语言包
  const parameterKeys = getURLParameters()
  if (!parameterKeys.includes('noLoadI18n')) {
    await loadBaseLang(appsJSONObj, apps?.apps?.i18nApp)
    // 判断如果是国际化app，加载前端静态资源
    let hasI18nApp = false
    if (apps?.apps?.i18nApp) {
      hasI18nApp = true
    } else {
      if (apps.apps) {
        let env = window?.tech?.env || 'master'
        for (let a in apps.apps) {
          let appItem = apps.apps[a]
          if (
            appItem?.[env]?.['tech-i18nApp'] ||
            appItem?.[env]?.['i18nApp'] ||
            appItem?.[env]?.['sie-iidp-i18n-web']
          ) {
            hasI18nApp = true
          }
        }
      }
    }
    // console.log(' === hasI18nApp == ', hasI18nApp)
    if (hasI18nApp) {
      window.techUseMultiLang = true // 添加使用多语言标识
      try {
        await loadStaticLangs()
      } catch (error) {
        window.techUseMultiLang = false
        console.log('----loadStaticLangs error ----', error)
      }
      // 按需加载扩展app语言
      await loadAppsLang(apps)
    } else {
      // 若没安装国际化app，则设置默认语言为中文
      const defaultLang = localStorage.getItem('defaultLang')
      // 移除地址上参数
      const removeURLParams = (url, paramsToRemove) => {
        const urlObj = new URL(url)
        const searchParams = urlObj.searchParams
        paramsToRemove.forEach((param) => {
          searchParams.delete(param)
        })
        urlObj.search = searchParams.toString()
        return urlObj.toString()
      }
      // 清除语言
      if (window.location.href.includes('?lang') || defaultLang) {
        const updatedURL = removeURLParams(window.location.href, ['lang'])
        localStorage.removeItem('defaultLang')
        sessionStorage.removeItem('tabs_meta_main_content_labels')
        window.location.href = updatedURL
      }
      await loadAppsLang(apps)
    }
  }
}

// 加载底座组件库语言包
export const loadBaseLang = async (appsJSONObj, hasI18nApp) => {
  // 在apps.json里面重新获取默认语言
  if (appsJSONObj?.defaultLang) {
    window.Tech.LANG.locale = appsJSONObj.defaultLang
  }
  // 若系统有默认语言，则使用系统默认语言
  let hasDefaultLang = false
  if (hasI18nApp) {
    try {
      const langs = await window.Tech.httpMeta({
        url: '/root/rpc/service',
        data: {
          // 参考元模型后端的传参规范
          params: {
            args: {},
            service: 'selectLangAfterLogin',
            model: 'mutil_language',
            app: 'sie-iidp-i18n'
          }
        }
      })
      if (langs && langs.data) {
        const defaultLang = langs.data.find((item) => {
          if (item.isDefault) {
            return item
          }
        })?.value
        if (defaultLang) {
          window.Tech.LANG.locale = defaultLang
          window.tech.complementLang = defaultLang
          window._completeLang = defaultLang
          hasDefaultLang = true
        }
      }
    } catch (e) {
      console.log(' === loadLang baseLangResArr error == ', e)
    }
  }
  if (window.localStorage && window.localStorage.getItem('defaultLang')) {
    window.Tech.LANG.locale = window.localStorage.getItem('defaultLang')
  }

  // 在apps.json里面重新获取默认语言定义缺失key后的补充语言
  if (appsJSONObj?.complementLang && !hasDefaultLang) {
    window._completeLang = appsJSONObj.complementLang
  }

  // 取url上面的问号参数 lang作为语言
  let curUrl = new URL(location.href)
  let urlParams = new URLSearchParams(curUrl.search)
  let urlLang = urlParams.get('lang')
  if (urlLang) {
    window.Tech.LANG.locale = decodeURIComponent(urlLang)
  }

  // 动态获取 weblib tbase 翻译文件
  let curLang = window.Tech.LANG.locale // 当前语言
  // console.log(' ==== curLang === ', curLang)
  let baseLangReqArr = [] // 请求默认语言数组
  let defaultLangReqArr = [] // 请求补充语言数组
  // 源码引入情况
  

  // 依赖包引入情况
  
  // 引入weblib多语言文件
  // baseLangReqArr.push(import('@tech/t-el-ui/langs/' + curLang + '/style.css'))
  baseLangReqArr.push(import('@tech/t-el-ui/langs/' + curLang + '/build.' + curLang + '.es.js'))
  // defaultLangReqArr.push(import('@tech/t-el-ui/langs/' + window._completeLang + '/style.css'))
  defaultLangReqArr.push(
    import(
      '@tech/t-el-ui/langs/' + window._completeLang + '/build.' + window._completeLang + '.es.js'
    )
  )
  // 引入base模板多语言文件
  // baseLangReqArr.push(import('@tech/t-base/langs/' + curLang + '/style.css'))
  baseLangReqArr.push(import('@tech/t-base/langs/' + curLang + '/build.' + curLang + '.es.js'))
  // defaultLangReqArr.push(import('@tech/t-base/langs/' + window._completeLang + '/style.css'))
  defaultLangReqArr.push(
    import(
      '@tech/t-base/langs/' + window._completeLang + '/build.' + window._completeLang + '.es.js'
    )
  )
  

  try {
    const baseLangResArr = await Promise.allSettled(baseLangReqArr)
    let failIndexs = [] // 收集失败的下标 方便按默认语言请求
    baseLangResArr.map((result, index) => {
      if (result.status !== 'rejected') {
        let item = result.value
        if (item) {
          let appendItem = item?.lang || item?.default?.lang || {}
          if (!window.Tech.LANG.langs[curLang]) {
            window.Tech.LANG.langs[curLang] = {}
          }
          // 动态合并语言
          window.Tech.LANG.langs[curLang] = {
            ...window.Tech.LANG.langs[curLang],
            ...appendItem
          }
        }
      } else {
        failIndexs.push(index)
      }
    })
    // console.log(' === failIndexs == ', failIndexs)
    // 拼接再次按补充语言请求数据
    let reTryReqArr = []
    failIndexs.map((itemF) => {
      if (defaultLangReqArr[itemF]) {
        reTryReqArr.push(defaultLangReqArr[itemF])
      }
    })
    if (reTryReqArr.length) {
      const reTryLangResArr = await Promise.allSettled(reTryReqArr)
      // console.log(' === reTryLangResArr == ', reTryLangResArr)
      reTryLangResArr.map((result, index) => {
        if (result.status !== 'rejected') {
          let item = result.value
          if (item) {
            let appendItem = item?.lang || item?.default?.lang || {}
            if (!window.Tech.LANG.langs[curLang]) {
              window.Tech.LANG.langs[curLang] = {}
            }
            // 动态合并语言
            window.Tech.LANG.langs[curLang] = {
              ...window.Tech.LANG.langs[curLang],
              ...appendItem
            }
          }
        }
      })
    }
  } catch (e) {
    console.log(' === loadLang baseLangResArr error == ', e)
  }

  // const [res1, res2] = await asyncAll([promise1, promise2]);
}

// 检测能否加载app
const checkCanLoadApp = (appDetail) => {
  // try {
  //   if (process?.env === 'development' && customProcess?.env === 'start') {
  //     // npm start 在开发环境都允许 非 npm run start:base情况
  //     return true
  //   }
  // } catch (e) {}
  let canLoad = true
  let hasLoaded = false
  // 处理 effectPaths 判断
  if (appDetail?.effectPaths) {
    // 获取当前pathname
    let replacePre = window?.tech?.routerBase || ''
    let pathName = window.tech_tmp_pathname || location.pathname
    // window.tech_tmp_pathname = null;
    let matchPathname = pathName || ''
    if (replacePre && pathName && matchPathname.startsWith(replacePre)) {
      matchPathname = pathName.replace(replacePre, '')
    }
    if (matchPathname === '') {
      // 空情况为 '/' 或 ''
      matchPathname = '/'
    }

    let matchPathname2 = matchPathname
    if (matchPathname.indexOf('/') !== 0) {
      matchPathname2 = '/' + matchPathname
    }
    // console.log(' === matchPathname === ', matchPathname);

    let effectPaths = appDetail.effectPaths
    if (effectPaths?.include) {
      if (
        effectPaths.include?.includes(matchPathname) ||
        effectPaths.include?.includes(matchPathname2)
      ) {
        // 判断影响页配置是否包含当pathname
        canLoad = true
        hasLoaded = true
      } else {
        canLoad = false
      }
    }
    if (effectPaths?.includeRegExp) {
      try {
        let includeRegExp = new RegExp(effectPaths.includeRegExp)
        if (includeRegExp.test(matchPathname) || includeRegExp.test(matchPathname2)) {
          canLoad = true
          hasLoaded = true
        } else {
          canLoad = false
        }
      } catch (e) {
        console.log(' === checkCanLoadApp effectPaths?.includeRegExp in reloadApps error == ', e)
      }
    }
    if (
      effectPaths?.exclude?.includes(matchPathname) ||
      effectPaths?.exclude?.includes(matchPathname2)
    ) {
      // 判断在不包含情况
      canLoad = false
    }
  }

  if (!window.tech) {
    window.tech = {}
  }
  if (window.tech.curPageId === undefined) {
    let curUrl = new URL(location.href)
    let urlParams = new URLSearchParams(curUrl.search)
    let pageId = urlParams.get('pageId')
    window.tech.curPageId = pageId || window?.tech_app?.page?.data?.id || 'page_meta_login'
  }

  if (!hasLoaded && appDetail?.effectPageIds && window?.tech?.curPageId !== undefined) {
    // 处理 effectPageIds 判断
    let effectPageIds = appDetail.effectPageIds
    if (effectPageIds?.include) {
      if (effectPageIds.include?.includes(window.tech.curPageId)) {
        // 判断影响页配置是否包含当前页
        canLoad = true
      } else {
        canLoad = false
      }
    }
    if (effectPageIds?.exclude?.includes(window.tech.curPageId)) {
      // 判断在不包含情况
      canLoad = false
    }
  }

  // *sub 子资源拆分
  if (appDetail?.sub) {
    for (let subName in appDetail.sub) {
      let subAllow = checkCanLoadApp(appDetail.sub[subName])
      if (subAllow) {
        if (!appDetail?.sub?.[subName]?.notDepParent) {
          // 若没有配置不依赖app
          canLoad = true // 如果app的子资源要加载 则app默认要加载
        }
      }
    }
  }

  return canLoad
}

// 加载apps里面的语言包
export const loadAppsLang = async (apps) => {
  if (window?.tech?.allowConcatResource) {
    // 定义收集路径变量 为concatResource拼接路径资源做准备
    let collectPaths = {}
    loadAppsLangRun(apps, collectPaths) // 运行前先收集路径

    // 处理concatResource合并资源路径 提前请求逻辑
    // console.log(' === collectPaths == ', collectPaths)
    let concatPaths = []
    Object.keys(collectPaths).map((typeKey) => {
      let time = []
      let paths = collectPaths[typeKey].map((it) => {
        let preStr = ''
        let lastStr = ''
        try {
          let sArr = it.split('?')
          preStr = sArr[0] // 去掉其他参数
          lastStr = sArr?.[1]?.split?.('=')?.[1] // 获取等号后面的时间参数
        } catch (e) {}
        time.push(lastStr)
        return preStr
      })
      // console.log(' === paths == ', paths)
      // console.log(' === time == ', time)
      concatPaths.push({
        type: typeKey,
        paths,
        time
      })
    })
    await window.Tech.reqConcatRes(concatPaths, { info: 'LangInitReq' })
    concatPaths = null
    collectPaths = null
  }
  let res = await loadAppsLangRun(apps) // 运行
  return res
}

// 加载apps里面的语言包处理
export const loadAppsLangRun = async (apps, collectPaths = null) => {
  window.techDevLocalLang = {}
  let isDevLocal = false
  try {
    if (
      process?.env === 'development'
      // && (customProcess?.env === 'start' || customProcess?.env === 'local') // 改造为开发环境都允许
    ) {
      // npm start 在开发环境都允许 非 npm run start:base情况
      isDevLocal = true
    }
  } catch (e) {}

  if (window?.Tech?.deepMerge) {
    let endAppReqArr = [] // 后端接口请求数组
    // console.log(' === apps === ', apps)
    let env = window?.tech?.env || 'master'
    let langAppArr = [] // 存放有多语言的数组
    if (apps?.appsDetail) {
      // console.log(' === in apps.appsDetail ')
      // 存在app详细信息情况
      let appsObj = apps.appsDetail
      for (let k in appsObj) {
        // 遍历apps结构
        let branchVersionObj = appsObj[k]?.[env] || {}
        for (let j in branchVersionObj) {
          // 若不允许加载则continue
          let checkPass = checkCanLoadApp(branchVersionObj[j]?.view_file_json)
          if (!checkPass) {
            if (!isDevLocal) {
              continue
            }
          }

          // 先处理依赖的后端app数组 depEndApps
          if (branchVersionObj[j]?.view_file_json?.depEndApps && !collectPaths) {
            try {
              branchVersionObj[j].view_file_json.depEndApps.map((depItem) => {
                endAppReqArr.push(window.techGetLangUseEndAppNew(depItem))
              })
            } catch (e) {
              console.log(' === depEndApps endAppReqArr.push error =', e)
            }
          } else if (branchVersionObj[j]?.view_file_json?.endApp && !collectPaths) {
            // 再处理依赖的后端app
            try {
              endAppReqArr.push(
                window.techGetLangUseEndAppNew(branchVersionObj[j].view_file_json.endApp)
              )
            } catch (e) {
              console.log(' === endAppReqArr.push error =', e)
            }
          }
          let appSupportLangs =
            branchVersionObj[j]?.view_file_json?.supportLangs ||
            branchVersionObj[j]?.view_file_json?.global?.supportLangs
          // 获取更新时间 url拼接去缓存
          let __packageTime =
            branchVersionObj[j]?.update_date ||
            branchVersionObj[j]?.view_file_json?.__packageTime ||
            branchVersionObj[j]?.view_file_json?.global?.__packageTime ||
            new Date().getTime()
          let pre = ''
          let appUrl = apps?.apps?.[k]?.[env]?.[j]
          if (appUrl && appUrl.indexOf('http') === 0) {
            if (appUrl.indexOf('/umdComps/') !== -1) {
              pre = appUrl.split('/umdComps/')[0]
            } else if (appUrl && appUrl.indexOf('/config/') !== -1) {
              pre = appUrl.split('/config/')[0] + '/'
            }
          }
          if (appSupportLangs) {
            // 应用app/config/config.json 有配置 supportLangs 加入处理
            langAppArr.push({
              appName: k,
              compName: j,
              supportLangs: appSupportLangs,
              reqLangFile: loadAppLangFile(
                k,
                j,
                { supportLangs: appSupportLangs, __packageTime, apps, env, collectPaths },
                pre
              ),
              resLangObj: null,
              checkPass
            })
          }
        }
      }
    } else {
      // console.log(' === in no apps.appsDetail ')

      // 不存在apps详细信息情况
      let reqAppList = []
      // console.log(' -------- apps --- ', apps)
      let appsObj = apps.apps
      for (let k in appsObj) {
        // 遍历apps结构
        let branchVersionObj = appsObj[k]?.[env] || {}
        for (let j in branchVersionObj) {
          let __packageTime = new Date().getTime()
          if (branchVersionObj[j].indexOf('?') !== -1) {
            __packageTime = branchVersionObj[j].split('?')[1]
          }
          let req = null
          // 开发模式命中 self本地开发app情况
          if (process?.env === 'development') {
            if (apps?.self?.[env]?.[k]) {
              if (customProcess?.baseFromNodeModule) {
                
                req = new Promise((resolve, reject) => {
                  import('../../../../../apps/' + k + '/config/app.json')
                    .then((res) => {
                      resolve(res?.default || res)
                    })
                    .catch((e) => {
                      reject(e)
                    })
                })
                
              } else {
                
              }
            } else {
              req = window.Tech.getFetch(branchVersionObj[j])
            }
          } else {
            req = window.Tech.getFetch(branchVersionObj[j])
          }
          // console.log(' === branchVersionObj[j] == ', branchVersionObj[j])
          reqAppList.push({
            appName: k,
            compName: j,
            __packageTime,
            req
          })
        }
      }
      // console.log(' === reqAppList == ', reqAppList)

      const appsResArr = await Promise.allSettled(reqAppList.map((itemL) => itemL.req))
      // console.log(' === appsResArr == ', appsResArr)
      // appsResArr.map((result, index) => {
      for (let z = 0; z < appsResArr.length; z++) {
        let result = appsResArr[z]
        let index = z

        if (result.status !== 'rejected') {
          let item = result.value
          // console.log(' === item == ', item)
          if (item) {
            // 若不允许加载则continue
            let checkPass = checkCanLoadApp(item)
            if (!checkPass) {
              if (!isDevLocal) {
                continue
              }
            }

            // 根据后端app调后端接口加载翻译键值对
            // 先处理依赖的后端app数组 depEndApps
            if (item?.depEndApps) {
              try {
                item.depEndApps.map((depItem) => {
                  endAppReqArr.push(window.techGetLangUseEndAppNew(depItem))
                })
              } catch (e) {
                console.log(' === depEndApps2 endAppReqArr.push error =', e)
              }
            } else if (item?.endApp) {
              try {
                endAppReqArr.push(window.techGetLangUseEndAppNew(item.endApp))
              } catch (e) {
                console.log(' === 2 endAppReqArr.push error =', e)
              }
            }

            // 应用app/config/config.json 有配置 supportLangs 加入处理
            let supportLangs = item?.supportLangs || item?.global?.supportLangs
            if (supportLangs) {
              let pre = ''
              let appUrl =
                apps?.apps?.[reqAppList[index].appName]?.[env]?.[reqAppList[index].compName]
              if (appUrl && appUrl.indexOf('http') === 0) {
                if (appUrl.indexOf('/umdComps/') !== -1) {
                  pre = appUrl.split('/umdComps/')[0]
                } else if (appUrl && appUrl.indexOf('/config/') !== -1) {
                  pre = appUrl.split('/config/')[0] + '/'
                }
              }
              langAppArr.push({
                appName: reqAppList[index].appName,
                compName: reqAppList[index].compName,
                supportLangs: supportLangs,
                reqLangFile: loadAppLangFile(
                  reqAppList[index].appName,
                  reqAppList[index].compName,
                  {
                    supportLangs: supportLangs,
                    __packageTime: reqAppList[index].__packageTime,
                    apps,
                    env
                  },
                  pre
                ),
                resLangObj: null,
                checkPass
              })
            }
          }
        }
      }
    }

    if (collectPaths) {
      // 收集情况 收集完返回
      return
    }

    // console.log(' === langAppArr == ', langAppArr)
    // 请求语言文件
    const langsResArr = await Promise.allSettled(langAppArr.map((itemL) => itemL.reqLangFile))
    // console.log(' === langsResArr == ', langsResArr)
    langsResArr.map((result, index) => {
      if (result && result.status !== 'rejected') {
        let item = result.value
        if (item) {
          // 合并语言
          try {
            let canMerge = true
            try {
              if (isDevLocal) {
                window.techDevLocalLang[langAppArr[index].compName] = item
                // 开发情况添加了允许多语言合并
                // if (!langAppArr[index].checkPass) {
                //   canMerge = false
                // }
              }
            } catch (e) {}
            if (canMerge) {
              let localeLang = window?.Tech?.LANG?.locale // 当前语言
              window.Tech.LANG.langs[localeLang] = window.Tech.deepMerge(
                window.Tech.LANG.langs[localeLang],
                item
              )
            }
          } catch (e) {
            console.log(' === in merge langs error === ', e)
          }
        }
      }
    })
    if (endAppReqArr?.length) {
      // 根据后端app请求后端接口的翻译键值对
      try {
        await Promise.allSettled(endAppReqArr)
      } catch (e) {
        console.log(' === endAppReqArr Promise.allSettled error =', e)
      }
    }
  }
}

// 加载app扩展里面的语言文件
export const loadAppLangFile = async (appName, compName, params, pre = '') => {
  // 获取url？后面的参数，如果存在noLoadI18n就不加载语言包
  const parameterKeys = getURLParameters()
  if (!parameterKeys.includes('noLoadI18n')) {
    let srcAppName = appName
    let concatMidPath = true // 请求lang资源是否拼接中间路径
    if (pre.indexOf('/webApps/') !== -1) {
      // 带 /webApps/ 为local启动 apps.json配置 http://iidp.chinasie.com:9999/webApps/ 引入外部app资源
      concatMidPath = false // 不拼接中间路径
    }
    if (!appName) {
      return
    }
    if (compName?.indexOf('tech-') === 0) {
      appName = compName.replace('tech-', '')
    } else {
      appName = compName
    }
    pre = pre.replace('/umdComps/' + compName + '/', '')
    if (pre.indexOf('/' + compName + '/') !== -1 || pre.indexOf('/' + appName + '/') !== -1) {
      concatMidPath = false // 不拼接中间路径
    }
    if (!window.techHaveHandlerFrontMultiApp) {
      window.techHaveHandlerFrontMultiApp = new Map()
    }
    if (window.techHaveHandlerFrontMultiApp.get(appName)) {
      if (window?.techDevLocalLang?.[compName]) {
        return window.techDevLocalLang[compName]
      }
      return false
    }
    // 若有配置frontHost则 替换pre
    let host = ''
    let search = window.location.search.substr(1) || window.location.hash.split('?')[1]
    let name = 'frontHost' // 若有配置 frontHost url参数则优先去这个参数
    let reg = new RegExp('(^|&)' + name + '=([^&]*)(&|$)')
    if (search) {
      let r = search.match(reg)
      let frontHost = ''
      if (r != null) {
        frontHost = decodeURIComponent(r[2])
      }
      // 添加非npm start情况
      if (frontHost && !(process?.env === 'development' && customProcess?.env === 'start')) {
        host = frontHost
        host = '//' + host
      }
    }
    try {
      // 若配置了sessionStorage 的 frontHost 则优先
      let sessionFrontHost = sessionStorage.getItem('frontHost')
      if (sessionFrontHost) {
        host = '//' + sessionFrontHost + '/'
      }
    } catch (e) {}
    if (host) {
      pre = host
    }

    let supportLangs = params?.supportLangs // app支持的语言
    let localeLang = window?.Tech?.LANG?.locale // 当前语言
    let addTime = params?.__packageTime || new Date().getTime()
    // console.log(' === inner supportLangs == ', supportLangs)
    // console.log(' === inner localeLang == ', localeLang)
    let appLocaleLang = localeLang
    // 若app没有对应的语言使用补全语言
    if (supportLangs && !supportLangs[localeLang] && window._completeLang) {
      appLocaleLang = window._completeLang
    }
    if (supportLangs && appLocaleLang) {
      // supportLangs && localeLang && supportLangs[localeLang]
      let apps = params.apps
      let env = params.env
      // window.Tech.LANG.langs
      // http://localhost/umdComps/tech-demo/resource/demo/langs/ja-JP/css.css?t=2023-12-09T09%3A50%3A09.000%2B00%3A00
      let midPath = '/umdComps/' + compName + '/'
      if (!concatMidPath) {
        midPath = ''
      }
      if (params?.apps?.appsDetail?.[srcAppName]?.[env]?.[compName]?.fromDev) {
        // 开发环境start:base情况加载本地开发app修改路径
        pre = ''
        midPath = ''
      }
      let cssPath =
        pre +
        midPath +
        'resource/' +
        appName +
        '/langs/' +
        appLocaleLang +
        '/css.css?t=' +
        encodeURIComponent(addTime + '')
      let reqCss = null

      let jsonPath =
        pre +
        midPath +
        'resource/' +
        appName +
        '/langs/' +
        appLocaleLang +
        '/lang.json?t=' +
        encodeURIComponent(addTime + '')
      let reqLangJSON = null
      let canCollect = false // 是否能收集拼接 concatResource

      // 开发模式命中 self本地开发app情况
      if (process?.env === 'development') {
        if (apps?.self?.[env]?.[appName]) {
          if (customProcess?.baseFromNodeModule) {
            
            reqCss = new Promise((resolve, reject) => {
              import(
                '../../../../../apps/' + appName + '/resource/langs/' + appLocaleLang + '/css.css'
              )
                .then((res) => {
                  resolve(res?.default || res)
                })
                .catch((e) => {
                  reject(e)
                })
            })
            reqLangJSON = new Promise((resolve, reject) => {
              import(
                '../../../../../apps/' + appName + '/resource/langs/' + appLocaleLang + '/lang.json'
              )
                .then((res) => {
                  resolve(res?.default || res)
                })
                .catch((e) => {
                  reject(e)
                })
            })
            
          } else {
            
          }
        } else {
          canCollect = true
          if (!params?.collectPaths) {
            if (!window.Tech.getConcatRes(cssPath)) {
              reqCss = window.Tech.asyncLoadCss(cssPath, document)
            } else {
              reqCss = new Promise((resolve) => {
                resolve()
              })
            }
            let jsonR = window.Tech.getConcatRes(jsonPath)
            if (!jsonR) {
              reqLangJSON = window.Tech.getFetch(jsonPath)
            } else {
              reqLangJSON = new Promise((resolve) => {
                resolve(jsonR)
              })
            }
          }
        }
      } else {
        canCollect = true
        if (!params?.collectPaths) {
          if (!window.Tech.getConcatRes(cssPath)) {
            reqCss = window.Tech.asyncLoadCss(cssPath, document)
          } else {
            reqCss = new Promise((resolve) => {
              resolve()
            })
          }
          let jsonR = window.Tech.getConcatRes(jsonPath)
          if (!jsonR) {
            reqLangJSON = window.Tech.getFetch(jsonPath)
          } else {
            reqLangJSON = new Promise((resolve) => {
              resolve(jsonR)
            })
          }
        }
      }

      // 处理concatResource合并资源路径 提前请求逻辑
      if (params?.collectPaths && canCollect) {
        if (!params.collectPaths.css) {
          params.collectPaths.css = []
        }
        if (!params.collectPaths.json) {
          params.collectPaths.json = []
        }
        params.collectPaths.css.push(cssPath)
        params.collectPaths.json.push(jsonPath)
        return
      }

      try {
        // console.log(' === cssPath == ', cssPath)
        await reqCss
      } catch (e) {
        // console.log(cssPath, ' ==== loadAppLangs css error === ', e)
      }
      try {
        // console.log(' === jsonPath == ', jsonPath)
        let jsonRes = await reqLangJSON
        // console.log(' === jsonRes == ', jsonRes)
        window.techHaveHandlerFrontMultiApp.set(appName, true)
        return jsonRes
      } catch (e) {
        console.log(jsonPath, ' ==== loadAppLangs js error === ', e)
      }
    }
  }
}

// 挂全局变量
window.techLoadAppLangFile = loadAppLangFile

// 获取译文接口中的前端静态数据
export const getStaticInternationlizationData = (list) => {
  let staticList = []
  for (let i = 0; i < list.length; i++) {
    if (list[i].views?.static) {
      staticList.push(list[i].views.static)
    }
  }
  let mergedObj = staticList.reduce((acc, curr) => {
    for (let key in curr) {
      if (key in acc) {
        acc[key] = window.Tech.deepMerge(acc[key], curr[key])
      } else {
        acc[key] = curr[key]
      }
    }
    return acc
  }, {})
  let resultList = [mergedObj]
  return resultList
}
// 获取前端国际化静态数据
export const loadStaticLangs = async () => {
  const localeLang = window?.Tech?.LANG?.locale // 当前语言
  const res = await window.Tech.httpMeta({
    url: '/rpc/open/service',
    data: {
      // 参考元模型后端的传参规范
      params: {
        args: {
          values: {
            languageFavorite: localeLang,
            appName: 'sie-iidp-i18n'
          }
        },
        service: 'getStaticResource',
        model: 'mutil_language',
        app: 'sie-iidp-i18n'
      }
    }
  })
  // 合并语言
  try {
    // const langList = res.data
    const langList = res.data?.staticResource
    // 存储静态资源
    window.Tech.staticIcon = res.data?.staticIcon
    const staticList = getStaticInternationlizationData(langList)
    // 深度合并后端返回的前端国际化静态数据
    for (let i = 0; i < staticList.length; i++) {
      window.Tech.LANG.langs[localeLang] = window.Tech.deepMerge(
        window.Tech.LANG.langs[localeLang],
        staticList[i]
      )
    }
  } catch (e) {
    console.log(' === in loadStaticLangs merge langs error === ', e)
  }
}
