import Vuex from 'vuex'

Vue.use(Vuex)

export default new Vuex.Store({
  state: {
    test: { a: 1 }
  },
  mutations: {
    changeTest(state, data) {
      Vue.set(state.test, 'a', data)
    }
  },
  actions: {
    changeTest({ commit }, data) {
      commit('changeTest', data)
    }
  },
  modules: {}
})
